-- Seed de GeoQuest: el banco de contenido del juego.
--
-- Se ejecuta automaticamente al final de `supabase db reset` (config.toml,
-- [db.seed] enabled = true), despues de todas las migraciones.
--
--
-- POR QUE ESTE FICHERO ES CRITICO
--
-- Mientras no exista stack local (D6 de INT-73), el proyecto remoto es el unico
-- entorno: `supabase db reset --linked` borra y reconstruye la base real. Todo
-- el contenido de trabajo tiene que poder reconstruirse desde aqui, porque lo
-- que solo exista dentro de la base se pierde en el primer reset y no hay vuelta
-- atras.
--
-- Dos cosas que las migraciones NO reconstruyen, y por eso viven aqui:
--
--   * `camino`: la migracion de INT-98 lo poblaba con un `select` sobre
--     `niveles`, y esa tabla la elimino INT-106. Hoy ese insert produce cero
--     filas, asi que sin este seed el camino queda vacio y no hay nada que
--     jugar.
--   * `dificultad_defaults`: las migraciones insertan los valores originales
--     (8 preguntas, 30-90 s). Los vigentes se han ajustado jugando
--     (4 preguntas, 20-30 s) y solo existian en la base.
--
--
-- QUE HAY Y QUE NO HAY AQUI
--
-- Hay contenido del juego, que es obra de autor y no se regenera:
--
--   dificultad_defaults      5 filas   configuracion por dificultad
--   tematicas                7 filas   categorias y su arte de portada
--   desafios               143 filas   el banco de preguntas
--   camino                   8 filas   la secuencia de paradas
--
-- No hay datos de jugadores: ni `profiles`, ni `intentos_nivel`, ni
-- `respuestas_desafio`, ni `progreso_usuario_nivel`, ni inventarios de
-- comodines. Son datos de uso, no contenido, y ademas cuelgan de `auth.users`.
--
--
-- SOBRE LAS IMAGENES
--
-- `tematicas.imagen_portada` y `desafios.imagen_url` son URLs absolutas al
-- bucket publico `challenge-media` de este proyecto de Supabase. El bucket es
-- publico, asi que estas filas funcionan tal cual desde cualquier proyecto: las
-- imagenes se sirven sin credenciales. La contrapartida es que siguen alojadas
-- en el proyecto original; una copia de verdad autosuficiente exigiria volver a
-- subir los ficheros y reescribir las URLs.
--
--
-- COMO SE REGENERA
--
-- Este fichero se genera desde la base, no se edita a mano. Si creas contenido
-- desde el panel y te importaria perderlo, vuelvelo a volcar.
--
-- Todos los bloques son `insert ... on conflict do update`: son idempotentes y
-- convergen al estado de aqui, asi que se pueden ejecutar sobre una base ya
-- poblada sin duplicar nada y sin borrar nada.
--
--   cd backend
--   supabase db query --linked -f supabase/seed.sql   # aplicar
--
-- El orden de los bloques respeta las claves ajenas: `tematicas` antes de
-- `desafios` y de `camino`, que la referencian.

on conflict (dificultad) do update set
  preguntas_por_partida = excluded.preguntas_por_partida, segundos_por_desafio = excluded.segundos_por_desafio;

on conflict (id) do update set
  nombre = excluded.nombre, orden = excluded.orden, activo = excluded.activo, imagen_portada = excluded.imagen_portada, prompt_imagen = excluded.prompt_imagen, objetivo_global = excluded.objetivo_global;

on conflict (id) do update set
  tematica_id = excluded.tematica_id, tipo = excluded.tipo, dificultad = excluded.dificultad, nombre = excluded.nombre, nombre_lugar = excluded.nombre_lugar, ciudad = excluded.ciudad, pais = excluded.pais, pista = excluded.pista, texto_pregunta = excluded.texto_pregunta, imagen_url = excluded.imagen_url, video_url = excluded.video_url, lat_real = excluded.lat_real, lng_real = excluded.lng_real, activo = excluded.activo;

on conflict (id) do update set
  orden = excluded.orden, tematica_id = excluded.tematica_id, dificultad = excluded.dificultad, nombre = excluded.nombre, activo = excluded.activo, preguntas_por_partida = excluded.preguntas_por_partida, segundos_por_desafio = excluded.segundos_por_desafio, created_at = excluded.created_at;
